/* ======================= My team: the stage ======================= */
MG.lineup = ms => { let F = null; try { F = CH.four(ms); } catch (e) {} const has = n => ms.some(m => m.p.n === n);
  if (F && F.lead && F.lead.every(has) && (F.back || []).every(has)) { const lead = F.lead.slice(0, 2).map(n => ms.find(m => m.p.n === n)), back = (F.back || []).slice(0, 2).map(n => ms.find(m => m.p.n === n)); return {lead, back, home: ms.filter(m => !lead.includes(m) && !back.includes(m)), by: 'meta'}; }
  return {lead: ms.slice(0, 2), back: ms.slice(2, 4), home: ms.slice(4), by: 'order'}; };
MG.team = () => { const head = $('chTeam'); if (!head) return; const six = head.querySelector('.rzsix'); if (!six || six.dataset.mg) return; const ms = members(); if (!ms.length) return;
  const L = MG.lineup(ms), sel = ui.rzSet;
  const btn = (m, g) => { const on = sel === m.i, role = {lead: 'Lead', back: 'Back'}[g];
    return MG.panel({p: m.p, mode: on ? 'lines' : 'dots', cls: 'mgst mg' + g + (on ? ' mgon' : ''), tag: 'button', attrs: `type="button" data-chset="${m.i}" aria-pressed="${on}" aria-controls="rzSet" aria-label="${esc(m.d)}, ${role.toLowerCase()}: show its set"`, cap: {role, side: 'you', name: m.d}}); };
  const bench = L.home.length ? `<div class="mgbench" role="group" aria-label="Bench"><span class="mgbl">Bench</span>${L.home.map(m => `<button type="button" class="mgbn tyx${sel === m.i ? ' mgon' : ''}" style="${tyVars(m.p)}" data-chset="${m.i}" aria-pressed="${sel === m.i}" aria-controls="rzSet" aria-label="${esc(m.d)}, bench: show its set">${MG.aura(m.p)}<span>${escName(m.d)}</span></button>`).join('')}</div>` : '';
  const st = document.createElement('div'); st.className = 'mgstage'; st.setAttribute('role', 'group'); st.setAttribute('aria-label', 'Your six: tap one to see its set');
  st.innerHTML = `<div class="mgstg">${L.lead.map(m => btn(m, 'lead')).join('')}${L.back.map(m => btn(m, 'back')).join('')}</div>${bench}`;
  six.dataset.mg = '1'; six.hidden = true; six.after(st);
  /* the grade: the app's own score (CH.gradeOf().s, the same number Home's 6v6 shows), big beside the name, "Grade A" plain,
     the "Why A?" button once; the record line keeps its facts without repeating "Grade A" */
  try { const RD = prepOf(ms), G = RD ? CH.gradeOf(RD, (ui.vsum || {}).CK, ms) : null, nm = head.querySelector('.chthead .nm'), gr = head.querySelector('.rzgrade');
    if (G && nm && !head.querySelector('.mgtgr')) { const why = gr && gr.querySelector('.rzwhy');
      const box = document.createElement('div'); box.className = 'mgtgr'; box.innerHTML = `<b class="mgmis" style="--mc:var(--chblue);--MC:var(--chblue)">${G.s}</b><span>Grade ${esc(G.letter)}</span>`;
      if (why) box.append(why); const row = document.createElement('div'); row.className = 'mgtrow'; nm.before(row); row.append(nm, box); if (gr) { gr.hidden = true; gr.classList.add('mgmoved'); }
      const rd0 = head.querySelector('.rd'); if (rd0) { const b0 = rd0.firstElementChild; if (b0 && b0.tagName === 'B' && /^Grade [A-F]/.test(b0.textContent)) { const nx = b0.nextSibling; b0.remove(); if (nx && nx.nodeType === 3) nx.textContent = nx.textContent.replace(/^:\s*/, ''); const t = rd0.firstChild; if (t && t.nodeType === 3) t.textContent = t.textContent.replace(/^\s*(\w)/, (m, c) => c.toUpperCase()); } } } } catch (e) {}
  /* the real app's "How to read our numbers" tip sits on the grade line; the trial's record wording dropped it, so it comes back */
  const rd = head.querySelector('.rd'); if (rd && !head.querySelector('[data-tip="numbers"]') && typeof tip === 'function') rd.insertAdjacentHTML('beforeend', ' ' + tip('numbers'));
  /* "Why A?" opens its explanation right under the grade (it used to open ~1,300px further down, past the stage, so on a phone nothing seemed to happen) */
  const gw = $('chGwhy'), trow = head.querySelector('.mgtrow'); if (gw && trow && trow.nextElementSibling !== gw) trow.after(gw);
  /* the tapped Pokémon's set opens right under the stage (moved up from under the team buttons) */
  const set = $('rzSet'); if (set) st.after(set);
  /* first visit: the first lead's set is open, so the stage shows its one burst (a tap anywhere else moves it) */
  if (ui.rzSet === undefined && L.lead[0] && !MG.pre) { MG.pre = 1; const f = st.querySelector(`[data-chset="${L.lead[0].i}"]`); if (f) setTimeout(() => { MG.auto = 1; f.click(); MG.auto = 0; }, 0); } };
document.addEventListener('click', e => { const b = e.target && e.target.closest && e.target.closest('.mgtgr [data-chgrade]'); if (!b) return;
  setTimeout(() => { const g = $('chGwhy'); if (g && !g.hidden) try { g.scrollIntoView({block: 'nearest', behavior: CH.reduced() ? 'auto' : 'smooth'}); } catch (x) {} }, 30); });
/* re-render the stage when a Pokémon is tapped (the app's own handler fills #rzSet) */
document.addEventListener('click', e => { const b = e.target && e.target.closest && e.target.closest('.mgstage [data-chset]'); if (!b) return; MG.autoNow = MG.auto;
  setTimeout(() => { const st = document.querySelector('.mgstage'), six = document.querySelector('#chTeam .rzsix'); if (!st || !six) return; st.remove(); delete six.dataset.mg; MG.team();
    const s = document.querySelector(`.mgstage [data-chset="${b.dataset.chset}"]`); if (s) { if (e.detail === 0 && !MG.autoNow) try { s.focus({preventScroll: true}); } catch (x) {} if (!CH.reduced()) { s.classList.add('mglift'); setTimeout(() => s.classList.remove('mglift'), 260); } } }, 0); });

/* ======================= Info sheet: the hero ======================= */
MG.sheet = n => { const sh = $('lairSheet'), p = n && byName.get(n); if (!sh || sh.hidden || !p) return; const head = sh.querySelector('.lshead'); if (!head || head.querySelector('.mghero')) return;
  let r = null, T = null; try { r = rating(p); T = lTier(r.total); } catch (e) {}
  const rk = typeof rankTxt === 'function' ? rankTxt(p, 'cap') : '';
  const cap = [T ? `${T.k} tier` : '', rk].filter(Boolean).join(', ');
  head.insertAdjacentHTML('afterbegin', MG.panel({p, mode: 'lines', cls: 'mghero', top: r ? `<span class="mgbig mgmis">${RS(r.total)}</span>${cap ? `<span class="mgcap mgcapq">${esc(cap)}</span>` : ''}` : ''}));
  head.classList.add('mghead');
  /* the rating cell under the hero repeats the hero's number: its "What a rating means" tip moves into the hero caption, the cell hides */
  const cell = sh.querySelector('.chlsr'), tq = cell && cell.querySelector('.tipq'), cq = head.querySelector('.mghero .mgcapq');
  if (cell && cq) { if (tq) cq.append(tq); cell.hidden = true; cell.classList.add('mgmoved'); }
  const stats = sh.querySelector('.chlstats');
  if (stats && !stats.querySelector('.mgspd')) { let r0 = null; try { r0 = LST.speeds(p).find(x => x.main) || null; } catch (e) {}
    if (r0) stats.insertAdjacentHTML('beforeend', `<div class="mgspd"><b>${r0.v}</b><span>Speed at level 50</span></div>`); }
  /* the main action sits right under the numbers, in the first screen */
  const add = sh.querySelector('.lsact [data-laddteam]'); if (stats && add && !sh.querySelector('.mgadd')) { const w = document.createElement('div'); w.className = 'mgadd'; stats.after(w); w.append(add); } };
CH.wrap('lairSheet', n => MG.sheet(n));

/* ======================= Battle mode: "The read" as a three-panel strip ======================= */
function rzReadHtml() {
  const mine = members(), theirs = oppTeam();
  if (mine.length < 4 || !theirs.length) return '';
  const r = planMatchup(mine, theirs, true), lead = r.lead.map(i => mine[i]), C = r.chosen.map(i => mine[i]);
  const ll = r.B && theirs.length >= 2 ? likelyLead(theirs, r.B) : [];
  let threat = null;
  try { const W = bmWatch(C, theirs); const hi = W.find(w => w.out.some(o => o[0] === 'hi')) || W[0]; if (hi) threat = {o: hi.o, t: (hi.out.find(o => o[0] === 'hi') || hi.out[0])[1]}; } catch (e) {}
  const fo = theirs.filter(o => (o.moves || []).some(x => x && x.name === 'Fake Out')).length;
  const pair = (a, b, side, lab, pic) => { const p = a.p;
    return `<div class="mgpn mgburst mgr1 ${side}" style="${MG.vars(p)}"><span class="mgin"><span class="mgwash"></span><span class="mglines"></span><span class="mgcap mgcapq">${MG.pic(pic)}<span><span class="mgrole ${side}">${lab}</span> ${escName(a.d)} and ${escName(b.d)}</span></span><span class="mgmon mgm2">${MG.aura(a.p)}${MG.aura(b.p)}</span></span></div>`; };
  const one = (o, side, lab, txt, pic) => `<div class="mgpn mgtone mgr2 ${side}" style="${MG.vars(o.p)}"><span class="mgin"><span class="mgdots"></span><span class="mgcap mgcapq">${MG.pic(pic)}<span><span class="mgrole ${side}">${lab}</span> ${escName(o.d)}${txt ? `<em>${txt}</em>` : ''}</span></span><span class="mgmon">${MG.aura(o.p)}</span></span></div>`;
  return `<div class="rzread mgread" role="region" aria-label="The read"><h2>The read</h2><div class="mgstrip">
    ${lead.length === 2 ? pair(lead[0], lead[1], 'you', 'Your lead', 'hit') : ''}
    ${ll.length === 2 ? `<div class="mgpn mgtone mgr2 them" style="${MG.vars(ll[0].p)}"><span class="mgin"><span class="mgdots"></span><span class="mgcap mgcapq">${MG.pic('fakeout')}<span><span class="mgrole them">Their lead</span> ${escName(ll[0].d)}, ${escName(ll[1].d)}</span></span><span class="mgmon mgm2">${MG.aura(ll[0].p)}${MG.aura(ll[1].p)}</span></span></div>` : ''}
    ${threat ? one(threat.o, 'them', 'Biggest threat', threat.o.d.toLowerCase().includes(String(threat.t).toLowerCase()) ? '' : threat.t, 'spread') : ''}
  </div><p class="mgfo">Fake Out on their side: <b>${fo}</b></p><span class="rzlive">Updates as you type their six</span></div>`;
}

/* ======================= Header, menu, bottom bar ======================= */
MG.chrome = () => { const row = document.querySelector('.band .titlerow'), side = $('side'); if (!row || !side || row.dataset.mg) return; row.dataset.mg = '1';
  /* desktop: one row — logo, the page tabs, search, ⋯ (the tabs move up into the header) */
  const tabs = document.querySelector('nav.tabs'); if (tabs) { const logo = row.firstElementChild; logo.after(tabs); tabs.classList.add('mgtabs'); }
  /* the theme controls move into the ⋯ menu (both: the day/night toggle and Auto / Light / Dark) */
  const g = document.createElement('div'); g.className = 'sgroup mgtheme'; g.innerHTML = '<div class="sgl">Theme</div>';
  document.querySelectorAll('.themeseg').forEach(x => g.append(x)); const tb = $('thmBtn'); if (tb) { tb.hidden = true; tb.classList.add('mgdup'); } /* the Auto / Light / Dark switch is the one theme control; the second icon-only toggle did the same thing */
  const top = side.querySelector('.sidetop'); if (top) top.after(g); else side.prepend(g);
  side.querySelectorAll('.sgroup').forEach(x => { if (x !== g && ![...x.children].some(c => !c.classList.contains('sgl') && c.offsetParent !== null && c.getBoundingClientRect().height > 0) && !x.querySelector('button,a,input')) x.classList.add('mgempty'); });
  /* bottom bar: My team is a line folder (as the mockups) */
  const fab = document.querySelector('.bnav [data-view="report"] .chfab svg'); if (fab) { fab.setAttribute('viewBox', '0 0 24 24'); fab.innerHTML = '<path d="M3 7.5V18a1.5 1.5 0 0 0 1.5 1.5h15A1.5 1.5 0 0 0 21 18V9a1.5 1.5 0 0 0-1.5-1.5h-8l-2-2.5h-5A1.5 1.5 0 0 0 3 6.5z" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linejoin="round"/>'; }
  const mt = null; if (mt) mt.innerHTML = '<path d="M3 7.5V18a1.5 1.5 0 0 0 1.5 1.5h15A1.5 1.5 0 0 0 21 18V9a1.5 1.5 0 0 0-1.5-1.5h-8l-2-2.5h-5A1.5 1.5 0 0 0 3 6.5z" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linejoin="round"/>'; };
MG.battle = () => { const pane = document.querySelector('[data-pane="matchup"]'), out = $('bmOut'); if (!pane || !out) return; const opp = out.querySelector('.bmopp'); if (!opp) return;
  /* order: Vs head, their six (likely leads marked), The read, then the calm tools (damage calc and practice after) */
  const fold = pane.querySelector('#muFold'); ['chCalcCard', 'oppQuick', 'prEntry'].forEach(id => { const x = $(id); if (x && fold && x.compareDocumentPosition(out) & Node.DOCUMENT_POSITION_FOLLOWING) fold.before(x); });
  const head = pane.querySelector('.chbmhead'), t = head && head.querySelector('.chbmt'), pg = head && head.querySelector('.chpgs');
  if (t && pg && !head.dataset.mg) { const bs = pg.querySelectorAll('b'), who = bs[0] && bs[0].textContent.trim(); if (who) { head.dataset.mg = '1'; const old = t.cloneNode(true); old.className = 'mgvsarch'; t.innerHTML = `Vs ${esc(who)}`; t.after(old); } }
  if (!opp.dataset.mg) { opp.dataset.mg = '1'; try { const mine = members(), theirs = oppTeam();
      if (mine.length >= 4 && theirs.length >= 2) { const r = planMatchup(mine, theirs, true), ll = r.B ? likelyLead(theirs, r.B).map(o => o.p.n) : [];
        opp.querySelectorAll('.bmslot').forEach(sl => { const n = (sl.querySelector('[data-oppx],[data-lt],button') || {}).dataset || {}; const nm = n.oppx || n.lt || ''; const hit = ll.find(x => sl.textContent.includes((byName.get(x) || {}).d || '~'));
          if (hit && !sl.querySelector('.mgll')) { sl.classList.add('mgllead'); sl.insertAdjacentHTML('beforeend', '<span class="mgll">Likely lead</span>'); } }); } } catch (e) {} } };
try { MG.chrome(); } catch (e) {}
/* sentence case on screen (Sim: no all-caps): words written in capitals in the copy (LOCK, MOST USED, MEGA STONE…) become sentence case.
   Real abbreviations stay (HP, OHKO, VGC, Reg M-C…). Runs after every redraw. */
MG.ABBR = new Set(['OHKO', '2HKO', '3HKO', '4HKO', '5HKO', 'HP', 'KO', 'OHKO', '2HKO', '3HKO', '4HKO', 'VGC', 'EV', 'EVs', 'IV', 'IVs', 'PP', 'STAB', 'TR', 'NAIC', 'EUIC', 'LAIC', 'OCIC', 'OK', 'ID', 'UI', 'URL', 'M-C', 'M-A', 'M-B', 'SV', 'DLC', 'CSV', 'PDF', 'BSS', 'AI', 'FAQ', 'API', 'USA', 'UK', 'RK9', 'VR', 'TPCi', 'TPC', 'PS', 'PC', 'TV', 'NB', 'WR', 'MIT', 'BY-SA', 'CC', 'BY', 'SA', 'GPL']);
MG.PROPER = {showdown: 'Showdown', 'pokémon': 'Pokémon', pokemon: 'Pokémon', mega: 'Mega', tera: 'Tera', champions: 'Champions', smogon: 'Smogon', limitless: 'Limitless', nastyplot: 'NastyPlot', regulation: 'Regulation'};
/* " · " lists become natural phrases: a label in front of a list takes a colon, a missing value ("—") is said in words */
MG.undot = (v, p) => { let out = v.replace(/—\s·\s/g, 'no power, ').replace(/ · /g, ', ');
  if (p.closest('.chk,.eyebrow,.sgl,.ltd,.npk') && !/:/.test(out)) out = out.replace(', ', ': ');
  return out; };
MG.capsText = t => { const words = t.match(/[0-9]*[A-Za-z][A-Za-z0-9'’-]*/g) || []; const caps = words.filter(w => w.length >= 3 && w === w.toUpperCase() && /[A-Z]/.test(w) && !MG.ABBR.has(w));
  if (!caps.length) return null; let first = true;
  return t.replace(/[0-9]*[A-Za-z][A-Za-z0-9'’-]*/g, w => { if (w.length >= 2 && w === w.toUpperCase() && !MG.ABBR.has(w) && /[A-Z]{2}/.test(w)) { const low = w.toLowerCase(), keep = MG.PROPER[low]; const o = keep || (first ? w[0] + w.slice(1).toLowerCase() : low); first = false; return o; } first = false; return w; }); };
MG.caps = () => { const w = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT); const L = []; let n; while ((n = w.nextNode())) if (/[A-Z]{3}/.test(n.nodeValue)) L.push(n);
  for (const t of L) { const p = t.parentElement; if (!p || p.closest('script,style,textarea,svg,code,pre,kbd,.np,.nplk,.sr')) continue; const v = MG.capsText(t.nodeValue); if (v != null && v !== t.nodeValue) t.nodeValue = v; }
  /* plain phrases, not dot strings: " · " becomes a comma everywhere except the footer link row */
  const w2 = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT); const D = []; while ((n = w2.nextNode())) if (n.nodeValue.includes(' · ')) D.push(n);
  for (const t of D) { const p = t.parentElement; if (!p || p.closest('script,style,textarea,svg,.lglinks,option')) continue; (window.__MGdots = window.__MGdots || new Set()).add(t.nodeValue.trim().slice(0, 90) + ' @' + (p.className || p.tagName)); t.nodeValue = MG.undot(t.nodeValue, p); } };
/* ======================= Ratings: the top two as the page's hero (Sim: "more flare") ======================= */
MG.ratings = () => { document.querySelectorAll('[data-pane="ratings"] .chhot:not(.mgrh)').forEach(h => { const p = byName.get(h.dataset.lt); if (!p) return;
  h.classList.add('mgrh'); h.setAttribute('style', (h.getAttribute('style') || '') + ';' + MG.vars(p));
  const n = h.querySelector('.n'), nm = h.querySelector('.nm'), st = h.querySelector('.st'), img = h.querySelector('img');
  if (n) { n.classList.add('mgmis'); }
  const rk = st && st.querySelector('.chrk'), rkT = rk ? rk.textContent.trim() : '';
  const lines = st ? st.innerHTML.split(/<br\s*\/?>/i).map(x => x.trim()).filter(Boolean) : [];
  const rows = lines.filter(x => !/chrk/.test(x)).map(x => `<span class="mgrrow">${x}</span>`).join('');
  /* plain words (Nov 9): a stat line marked .dbsec stays behind Details here too, rank pill included */
  const hid = !!(st && st.classList.contains('dbsec'));
  if (st) st.outerHTML = `<span class="mgrst${hid ? ' dbsec' : ''}">${rows}</span>`;
  if (rkT) nm.insertAdjacentHTML('beforebegin', `<span class="mgcap mgrcap${hid ? ' dbsec' : ''}">${esc(rkT)}</span>`);
  if (img) { const w = document.createElement('span'); w.className = 'mgrmon'; w.innerHTML = MG.aura(p); img.replaceWith(w); }
  h.insertAdjacentHTML('afterbegin', '<span class="mgin"><span class="mgwash"></span><span class="mglines"></span></span>'); }); };

/* ======================= A little more manga on the calm pages ======================= */
MG.PAGEHUE = {meta: 'Psychic', ratings: 'Dragon', calc: 'Fire', speed: 'Electric', events: 'Water', top: 'Fighting', sets: 'Grass', teams: 'Flying', box: 'Ground', coverage: 'Fairy', types: 'Normal', arch: 'Ghost', gauntlet: 'Steel', weekly: 'Ice', track: 'Rock', practice: 'Bug', method: 'Poison', about: 'Water', compare: 'Flying', cores: 'Grass', auto: 'Fire'};
MG.flair = () => { document.querySelectorAll('[data-pane]').forEach(pane => { const v = pane.dataset.pane; if (v === 'home' || v === 'report' || v === 'matchup' || pane.hidden) return;
    const t = pane.querySelector('.chpgt'); if (t && !t.closest('.mgtitle')) { const k = t.previousElementSibling && t.previousElementSibling.classList.contains('chk') ? t.previousElementSibling : null;
      const w = document.createElement('div'); w.className = 'mgtitle'; const hue = MG.PAGEHUE[v] || 'Normal';
      w.setAttribute('style', `--d1:${MG.at(hue, .78, .12)};--D1:${MG.at(hue, .45, .10)}`); t.before(w); w.innerHTML = '<span class="mgtdots" aria-hidden="true"></span>'; if (k) w.append(k); w.append(t);
      w.insertAdjacentHTML('beforeend', '<span class="mgtstroke" aria-hidden="true"></span>'); }
    /* one divider before the folds at the foot of a page (major section break) */
    const f = pane.querySelector('.chsec.chfold, .chfolds'); if (f && !(f.previousElementSibling && f.previousElementSibling.classList.contains('mgdiv'))) f.insertAdjacentHTML('beforebegin', '<div class="mgdiv" aria-hidden="true"><i></i><i></i><i></i></div>');
    /* empty states: one small panel, an inked Pokémon and a caption */
    pane.querySelectorAll('.empty-note:not(.mgempty), .hempty:not(.mgempty)').forEach(e => { if (!e.offsetParent || e.querySelector('.mgeart')) return; e.classList.add('mgempty');
      const six = CH.metaSix(), q = six[(v.length) % Math.max(1, six.length)]; /* Darkrai (Sim, Nov 9) instead of a meta Pokémon, only on the approved empty screens and loading: Saved Teams, My Box, Test run,
         Build for Me, and the Events / Cores searches. Never the Battle preview or next to grades and data (they keep the meta Pokémon). */
      const dk = MG.DK_PANES.has(pane.dataset && pane.dataset.pane) && typeof AR === 'object' && AR.mascot ? AR.mascot() : null;
      if (dk || q) e.insertAdjacentHTML('afterbegin', `<span class="mgeart" aria-hidden="true">${dk || sprite(q) || ''}</span>`); }); }); };
MG.DK_PANES = new Set(['teams', 'box', 'gauntlet', 'auto', 'events', 'cores']);
/* tap feedback: a 150ms ink impact flick on main buttons and tappable Pokémon (none with reduced motion) */
document.addEventListener('pointerdown', e => { if (CH.reduced()) return; const b = e.target && e.target.closest && e.target.closest('.chprimary,.mgyel,#saveBtn,[data-lt],[data-chset],.mgact'); if (!b) return;
  b.classList.remove('mgimp'); void b.offsetWidth; b.classList.add('mgimp'); setTimeout(() => b.classList.remove('mgimp'), 160); }, {passive: true});

/* run after the app draws Home and My team */
CH.wrap('chTeamRender', () => MG.team());
{ let q = false; const run = () => { q = false; try { MG.home(); } catch (e) {} try { MG.team(); } catch (e) {} try { MG.battle(); } catch (e) {} try { MG.chrome(); } catch (e) {} try { MG.caps(); } catch (e) {} try { MG.ratings(); } catch (e) {} try { MG.flair(); } catch (e) {} };
  new MutationObserver(() => { if (!q) { q = true; requestAnimationFrame(run); } }).observe(document.body, {childList: true, subtree: true}); }
if (window.__PL_TEST) { window.__MG = MG; window.__MGopen = n => lairSheet(n); }
